from ocean_sonar.crosspoint import pair_gate_quality
FIRST=[(0.,0.,10.),(1.,0.,5.),(2.,0.,8.)]
SECOND=[(0.,0.,10.25),(1.,0.,4.75),(2.,0.,7.5)]
TOL=[0.5,1.0]
# huge ints -> ValueError, never OverflowError
for kw in ('min_coverage','min_score'):
    for v in (10**400, -10**400):
        try:
            pair_gate_quality(FIRST, SECOND, TOL, **{kw:v})
            raise SystemExit('no error')
        except ValueError as e:
            print(kw, v < 0, 'ValueError:', e)
        except OverflowError:
            raise SystemExit('OverflowError leak')
# non-finite floats
for kw,v in (('min_coverage',float('nan')),('min_coverage',float('inf')),('min_score',float('inf'))):
    try:
        pair_gate_quality(FIRST, SECOND, TOL, **{kw:v})
    except ValueError as e:
        print(kw, 'ValueError:', e)
# bool / wrong type
for kw,v in (('min_coverage',True),('min_score',False),('min_coverage','1')):
    try:
        pair_gate_quality(FIRST, SECOND, TOL, **{kw:v})
    except TypeError as e:
        print(kw, 'TypeError:', e)
# happy path structure and key order
r = pair_gate_quality(FIRST, SECOND, TOL)
print(list(r.keys()), list(r['checks'].keys()), r['checks'], r['quality'])
from ocean_sonar.crosspoint import pair_gate_score_summary
R = pair_gate_score_summary(FIRST, SECOND, TOL, 1.0, 1.0, 1.0)
print('report is R:', r['report'] is R if False else r['report']['summary'] is R['summary'])
# threshold order: min_coverage bad type must win even when min_score also bad
try:
    pair_gate_quality(FIRST, SECOND, TOL, min_coverage=True, min_score=999)
except TypeError as e:
    print('order ok:', e)
